#!/usr/bin/env bash
# regenerate_if_stale.sh -- the index-regeneration SEAM for constitution amendments (R4-01).
#
# Why it exists: constitution_index.yaml records `generated_from.source_sha256`, the sha256 of the
# Constitution.md it was generated from, and anchor_citations.py refuses a stale index
# (E_INDEX_SHA_MISMATCH, exit 4, BLIND). Before this script, nothing regenerated the index when
# Constitution.md changed: 59 of the last 60 commits that touched Constitution.md left it stale, so
# every amendment would blind the tool until someone regenerated by hand.
#
# What it does (idempotent):
#   1. takes an exclusive flock (concurrent invocations serialise; the losers then see "fresh");
#   2. compares sha256(Constitution.md) with the index's generated_from.source_sha256;
#   3. equal  -> prints "fresh: ..." and touches NOTHING (exit 0);
#      differs (or the index / its checksum is missing) -> regenerates index + groups/*.md with the
#      real generator (constitution_generate.py generate) into a temporary directory NEXT TO the
#      outputs, re-hashes the source (an edit made during generation aborts: exit 3, nothing
#      replaced), then replaces each changed file with an atomic rename -- group files first,
#      the index LAST, so the index never claims a checksum its groups do not match -- removes
#      group .md files the generator no longer produces, and prints every file it changed.
#   Group sibling exports (.html/.pdf/.docx) are NOT generated here (a separate exporter owns them);
#   when a group .md changes the script says so, it never pretends the exports are current.
#
# Usage:
#   regenerate_if_stale.sh [--root DIR] [--source FILE] [--groups-dir DIR] [--index-out FILE]
#                          [--check] [--lock FILE] [--lock-timeout SECONDS]
#     --root          constitution root (default: two levels above this script)
#     --source        default <root>/Constitution.md
#     --groups-dir    default <root>/groups
#     --index-out     default <root>/constitution_index.yaml
#     --check         report only: exit 0 fresh, 1 stale; never writes, takes no lock
#     --lock          lock file (default: `git rev-parse --git-path constitution-index-regen.lock`
#                     when <root> is in a git work tree, else <index-out>.lock)
#     --lock-timeout  seconds to wait for the lock (default 120)
#
# Exit codes: 0 fresh or regenerated; 1 stale (--check only); 2 usage; 3 regeneration failed or the
# source changed during regeneration (nothing replaced); 4 BLIND (source/generator unreadable);
# 75 lock not acquired within --lock-timeout (nothing written).
#
# Test-only hook: REGEN_TEST_HOOK_AFTER_GENERATE, when set, is evaluated after generation and before
# the source is re-hashed (used by tests/test_regenerate_if_stale.sh R6 to simulate a concurrent edit).
set -uo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
GEN="$HERE/constitution_generate.py"
ROOT="$(cd "$HERE/../.." && pwd)"
SOURCE=""; GROUPS_DIR=""; INDEX=""; CHECK=0; LOCK=""; LOCK_TIMEOUT=120

usage() { sed -n '24,34p' "$0" >&2; exit 2; }
while [ $# -gt 0 ]; do
  case "$1" in
    --root) [ $# -ge 2 ] || usage; ROOT=$2; shift 2 ;;
    --source) [ $# -ge 2 ] || usage; SOURCE=$2; shift 2 ;;
    --groups-dir) [ $# -ge 2 ] || usage; GROUPS_DIR=$2; shift 2 ;;
    --index-out) [ $# -ge 2 ] || usage; INDEX=$2; shift 2 ;;
    --check) CHECK=1; shift ;;
    --lock) [ $# -ge 2 ] || usage; LOCK=$2; shift 2 ;;
    --lock-timeout) [ $# -ge 2 ] || usage; LOCK_TIMEOUT=$2; shift 2 ;;
    -h|--help) usage ;;
    *) echo "regenerate_if_stale: unknown argument: $1" >&2; usage ;;
  esac
done
case "$LOCK_TIMEOUT" in ''|*[!0-9]*) echo "regenerate_if_stale: --lock-timeout must be a whole number" >&2; exit 2 ;; esac
SOURCE=${SOURCE:-$ROOT/Constitution.md}
GROUPS_DIR=${GROUPS_DIR:-$ROOT/groups}
INDEX=${INDEX:-$ROOT/constitution_index.yaml}
GROUPS_DIR=${GROUPS_DIR%/}

for dep in python3 flock sha256sum cmp; do
  command -v "$dep" >/dev/null 2>&1 || { echo "regenerate_if_stale: BLIND -- required dependency '$dep' not usable" >&2; exit 4; }
done
[ -f "$GEN" ] || { echo "regenerate_if_stale: BLIND -- generator absent: $GEN" >&2; exit 4; }
[ -f "$SOURCE" ] && [ -r "$SOURCE" ] || { echo "regenerate_if_stale: BLIND -- source unreadable: $SOURCE" >&2; exit 4; }

file_sha() { sha256sum < "$1" | cut -c1-64; }
# The index's generated_from.source_sha256 (empty when the index or the field is absent). Read with
# the same bounded block rule anchor_citations.py uses, never a whole-file grep.
index_sha() {
  [ -f "$1" ] || return 0
  python3 - "$1" <<'PY'
import re, sys
inside = False
for line in open(sys.argv[1], encoding="utf-8", errors="replace").read().split("\n"):
    if re.match(r"^generated_from:\s*$", line):
        inside = True
        continue
    if inside:
        if not line.startswith((" ", "\t")):
            break
        m = re.match(r"^\s+source_sha256:\s*'?([0-9a-f]{64})'?\s*$", line)
        if m:
            print(m.group(1))
            break
PY
}

want=$(file_sha "$SOURCE")
if [ "$CHECK" -eq 1 ]; then
  have=$(index_sha "$INDEX")
  if [ "$have" = "$want" ]; then
    echo "fresh: $INDEX source_sha256 matches $SOURCE ($want)"; exit 0
  fi
  echo "stale: $INDEX source_sha256 '${have:-<absent>}' != sha256 $want of $SOURCE -- run $HERE/regenerate_if_stale.sh"
  exit 1
fi

if [ -z "$LOCK" ]; then
  gp=$(git -C "$ROOT" rev-parse --git-path constitution-index-regen.lock 2>/dev/null) || gp=""
  case "$gp" in
    "") LOCK="$INDEX.lock" ;;
    /*) LOCK=$gp ;;
    *) LOCK="$ROOT/$gp" ;;
  esac
fi
exec 9>>"$LOCK" || { echo "regenerate_if_stale: BLIND -- cannot open lock file $LOCK" >&2; exit 4; }
if ! flock -w "$LOCK_TIMEOUT" 9; then
  echo "regenerate_if_stale: could not take the lock $LOCK within ${LOCK_TIMEOUT}s -- another regeneration is running; nothing written" >&2
  exit 75
fi

# Re-read both sides UNDER the lock: a concurrent run may have regenerated meanwhile.
want=$(file_sha "$SOURCE")
have=$(index_sha "$INDEX")  # under the lock
if [ "$have" = "$want" ]; then  # fresh under the lock
  echo "fresh: $INDEX source_sha256 matches $SOURCE ($want); nothing to do"
  exit 0
fi

PARENT=$(dirname "$INDEX")
STAGE=$(mktemp -d "$PARENT/.regen.XXXXXX") || { echo "regenerate_if_stale: BLIND -- cannot create a staging directory in $PARENT" >&2; exit 4; }
trap 'rm -rf "$STAGE"' EXIT
if ! python3 "$GEN" generate --source "$SOURCE" --groups-dir "$STAGE/groups" --index-out "$STAGE/constitution_index.yaml" > "$STAGE/gen.out" 2>&1; then
  echo "regenerate_if_stale: generation FAILED; nothing replaced:" >&2
  sed 's/^/  /' "$STAGE/gen.out" >&2
  exit 3
fi
if [ -n "${REGEN_TEST_HOOK_AFTER_GENERATE:-}" ]; then
  eval "$REGEN_TEST_HOOK_AFTER_GENERATE"
fi
after=$(file_sha "$SOURCE")
if [ "$after" != "$want" ]; then
  echo "regenerate_if_stale: $SOURCE changed during regeneration ($want -> $after); nothing replaced -- run again" >&2
  exit 3
fi
staged=$(index_sha "$STAGE/constitution_index.yaml")
if [ "$staged" != "$want" ]; then
  echo "regenerate_if_stale: the generated index records source_sha256 '$staged', not $want; nothing replaced" >&2
  exit 3
fi

mkdir -p "$GROUPS_DIR" || { echo "regenerate_if_stale: cannot create $GROUPS_DIR" >&2; exit 3; }
# The generator's own output set, recorded BEFORE anything is moved out of the staging directory.
(cd "$STAGE/groups" && for f in *.md; do [ -e "$f" ] && printf '%s\n' "$f"; done) > "$STAGE/generated_names"
changed=0
md_changed=0
while IFS= read -r name; do
  f="$STAGE/groups/$name"
  if [ -f "$GROUPS_DIR/$name" ] && cmp -s "$f" "$GROUPS_DIR/$name"; then continue; fi
  if [ -f "$GROUPS_DIR/$name" ]; then verb=updated; else verb=added; fi
  # Same filesystem as the target (the staging dir is its sibling), so mv is an atomic rename.
  mv -f -- "$f" "$GROUPS_DIR/$name" || { echo "regenerate_if_stale: cannot replace $GROUPS_DIR/$name" >&2; exit 3; }
  echo "$verb: groups/$name"
  changed=$((changed + 1)); md_changed=1
done < "$STAGE/generated_names"
# A group .md the generator no longer produces would otherwise linger (its exports are not touched).
for existing in "$GROUPS_DIR"/*.md; do
  [ -e "$existing" ] || continue
  name=$(basename "$existing")
  if ! grep -qxF -- "$name" "$STAGE/generated_names"; then
    rm -f -- "$GROUPS_DIR/$name"
    echo "removed: groups/$name"
    changed=$((changed + 1)); md_changed=1
  fi
done
# The index LAST: it is the commit point that claims the groups match the source.
mv -f -- "$STAGE/constitution_index.yaml" "$INDEX" || { echo "regenerate_if_stale: cannot replace $INDEX" >&2; exit 3; }
echo "updated: $(basename "$INDEX")"
changed=$((changed + 1))
if [ "$md_changed" -eq 1 ]; then
  echo "note: group .md files changed; their .html/.pdf/.docx exports are NOT regenerated by this script"
fi
echo "regenerated: $changed file(s); $INDEX source_sha256 is now $want"
exit 0
